# Lliçons del mòdul «Màrqueting en l'activitat comercial» (4/4): comerç integrat, comunicació i pla de màrqueting
L = [
dict(slug='comercio-integrado-asociado', id='M_cadenas', orden=22, codigos=['6.7'], fase=4,
 es=dict(titulo='Cadenas, franquicias y cooperativas', objetivo='Distinguir el comercio independiente, asociado e integrado.',
  tira=[[('eco','alegria','¡Abro tienda en Tona y en Torelló! ¡Ya soy una cadena!')],[('nexo','pensativo','¿Las abres tú o dejas que otros las abran con tu marca pagándote?')],[('eco','confusion','¿Hay diferencia?'),('nexo','guino','Mucha: cadena o franquicia.')]],
  cos='El <b>comercio independiente</b> es una tienda con un solo propietario que decide todo. El <b>comercio integrado</b> es una sola empresa con muchas tiendas: <b>cadenas sucursalistas</b> (todas de la misma empresa, con la misma marca y las mismas compras centralizadas), grandes almacenes, hipermercados.\n\nEn el <b>comercio asociado</b> los comercios siguen siendo independientes pero se unen para comprar mejor o compartir marca: <b>cooperativas de detallistas</b>, <b>centrales de compra</b>, <b>cadenas voluntarias</b> (mayorista + detallistas) y <b>franquicias</b>. En la franquicia, el <b>franquiciador</b> cede la marca, el saber hacer y el apoyo, y el <b>franquiciado</b> pone la inversión, gestiona su tienda y paga un canon y royalties.',
  ejemplo='En Mercadeja, en la fase de cadena abres tiendas en otros pueblos con un gerente en cada una: es una cadena sucursalista, porque todas son de tu empresa.',
  errores=['Pensar que el franquiciado es un empleado: es un empresario con su propia tienda.','Abrir tiendas sin comprobar que cada una cubre su alquiler y su personal.'],
  test=[('Todas las tiendas son de la misma empresa y compran de forma centralizada. Es…',['Comercio independiente','Una cadena sucursalista (comercio integrado)','Una cooperativa de detallistas','Una franquicia'],1,'Una sola empresa con muchas tiendas.'),
   ('En una franquicia, quien pone la inversión de la tienda y paga royalties es…',['El franquiciador','El franquiciado','El mayorista','La central de compras'],1,'El franquiciado explota la tienda con la marca del franquiciador.'),
   ('Varias tiendas independientes se unen para comprar juntas y conseguir mejores precios. Es…',['Una central de compras (comercio asociado)','Una cadena sucursalista','Un gran almacén','Un hipermercado'],0,'Siguen siendo independientes, pero compran juntas.'),
   ('Caso real · Muchas tiendas de alimentación de barrio funcionan con la enseña de una gran cadena (por ejemplo, Spar o Dia), pero son de propietarios independientes. ¿Qué modelo suele ser?',['Cadena sucursalista','Franquicia o cadena voluntaria','Comercio independiente sin ninguna relación','Venta sin establecimiento'],1,'El propietario es independiente, pero usa la marca y los proveedores de la cadena.')]),
 ca=dict(titulo='Cadenes, franquícies i cooperatives', objetivo='Distingir el comerç independent, associat i integrat.',
  tira=[[('eco','alegria','Obro botiga a Tona i a Torelló! Ja soc una cadena!')],[('nexo','pensativo','Les obres tu o deixes que d\'altres les obrin amb la teva marca pagant-te?')],[('eco','confusion','Hi ha diferència?'),('nexo','guino','Molta: cadena o franquícia.')]],
  cos='El <b>comerç independent</b> és una botiga amb un sol propietari que ho decideix tot. El <b>comerç integrat</b> és una sola empresa amb moltes botigues: <b>cadenes sucursalistes</b> (totes de la mateixa empresa, amb la mateixa marca i les mateixes compres centralitzades), grans magatzems, hipermercats.\n\nEn el <b>comerç associat</b> els comerços continuen sent independents però s\'uneixen per comprar millor o compartir marca: <b>cooperatives de detallistes</b>, <b>centrals de compra</b>, <b>cadenes voluntàries</b> (majorista + detallistes) i <b>franquícies</b>. En la franquícia, el <b>franquiciador</b> cedeix la marca, el saber fer i el suport, i el <b>franquiciat</b> posa la inversió, gestiona la seva botiga i paga un cànon i royalties.',
  ejemplo='A Mercadeja, en la fase de cadena obres botigues en altres pobles amb un gerent a cadascuna: és una cadena sucursalista, perquè totes són de la teva empresa.',
  errores=['Pensar que el franquiciat és un treballador: és un empresari amb la seva pròpia botiga.','Obrir botigues sense comprovar que cadascuna cobreix el lloguer i el personal.'],
  test=[('Totes les botigues són de la mateixa empresa i compren de manera centralitzada. És…',['Comerç independent','Una cadena sucursalista (comerç integrat)','Una cooperativa de detallistes','Una franquícia'],1,'Una sola empresa amb moltes botigues.'),
   ('En una franquícia, qui posa la inversió de la botiga i paga royalties és…',['El franquiciador','El franquiciat','El majorista','La central de compres'],1,'El franquiciat explota la botiga amb la marca del franquiciador.'),
   ('Diverses botigues independents s\'uneixen per comprar juntes i aconseguir millors preus. És…',['Una central de compres (comerç associat)','Una cadena sucursalista','Uns grans magatzems','Un hipermercat'],0,'Continuen sent independents, però compren juntes.'),
   ('Cas real · Moltes botigues d\'alimentació de barri funcionen amb l\'ensenya d\'una gran cadena (per exemple, Spar o Dia), però són de propietaris independents. Quin model sol ser?',['Cadena sucursalista','Franquícia o cadena voluntària','Comerç independent sense cap relació','Venda sense establiment'],1,'El propietari és independent, però fa servir la marca i els proveïdors de la cadena.')])),

dict(slug='mix-comunicacion-publicidad', id='M_publicidad', orden=23, codigos=['7.1', '7.2', '7.8'], fase=5,
 es=dict(titulo='El mix de comunicación y la publicidad', objetivo='Conocer los instrumentos de comunicación y elegir medios y presupuesto según el objetivo.',
  tira=[[('eco','alegria','¡Anuncio en la tele para mi tienda de barrio!')],[('nexo','esceptico','Pagarás para que te vea media Cataluña… que no vendrá nunca a tu calle.')],[('nexo','guino','Cuando tengas tiendas en toda la comarca, hablamos.')]],
  cos='El <b>mix de comunicación</b> combina cinco instrumentos: <b>publicidad</b> (comunicación pagada y masiva en medios), <b>promoción de ventas</b> (incentivos a corto plazo), <b>relaciones públicas</b> (imagen y relación con el entorno), <b>venta personal</b> y <b>marketing directo</b> (mensajes personalizados).\n\nEn publicidad se distinguen los <b>medios</b> (televisión, radio, prensa, exterior, cine, internet) y los <b>soportes</b> (un canal, un periódico, una web concreta). Se eligen según el público al que queremos llegar, el alcance y el coste por impacto.\n\nAntes de comunicar se fijan <b>objetivos</b> (dar a conocer, informar, persuadir, recordar) y un <b>presupuesto</b>: un porcentaje de las ventas, lo mismo que la competencia, lo que nos podemos permitir o, mejor, lo necesario para cumplir el objetivo.',
  ejemplo='En Mercadeja, la publicidad en la radio local y las redes sociales tienen sentido desde el principio; el anuncio en televisión solo cuando eres gran empresa con tiendas en toda la comarca.',
  errores=['Elegir el medio porque es famoso, no porque llega a tus clientes.','Comunicar sin objetivo: no sabrás si ha funcionado.'],
  test=[('¿Cuál es un medio publicitario y no un soporte?',['La radio','Un programa concreto de Catalunya Ràdio','La web de un diario concreto','Una revista concreta'],0,'El medio es la categoría; el soporte, el vehículo concreto.'),
   ('Un objetivo de comunicación de una tienda que acaba de abrir suele ser…',['Recordar','Dar a conocer (notoriedad)','Fidelizar a los clientes de siempre','Subir los precios'],1,'Nadie la conoce todavía.'),
   ('Fijar el presupuesto de publicidad como el 2 % de las ventas es el método…',['Del objetivo y la tarea','Del porcentaje sobre ventas','De la paridad competitiva','De lo que se pueda'],1,'Es fácil, pero si las ventas bajan, se comunica menos justo cuando más falta hace.'),
   ('¿Qué instrumento del mix de comunicación es una degustación gratuita en la tienda?',['Publicidad','Promoción de ventas','Relaciones públicas','Venta personal'],1,'Es un incentivo a corto plazo para que lo prueben.')]),
 ca=dict(titulo='El mix de comunicació i la publicitat', objetivo='Conèixer els instruments de comunicació i triar mitjans i pressupost segons l\'objectiu.',
  tira=[[('eco','alegria','Anunci a la tele per a la meva botiga de barri!')],[('nexo','esceptico','Pagaràs perquè et vegi mitja Catalunya… que no vindrà mai al teu carrer.')],[('nexo','guino','Quan tinguis botigues a tota la comarca, en parlem.')]],
  cos='El <b>mix de comunicació</b> combina cinc instruments: <b>publicitat</b> (comunicació pagada i massiva en mitjans), <b>promoció de vendes</b> (incentius a curt termini), <b>relacions públiques</b> (imatge i relació amb l\'entorn), <b>venda personal</b> i <b>màrqueting directe</b> (missatges personalitzats).\n\nEn publicitat es distingeixen els <b>mitjans</b> (televisió, ràdio, premsa, exterior, cinema, internet) i els <b>suports</b> (un canal, un diari, un web concret). Es trien segons el públic al qual volem arribar, l\'abast i el cost per impacte.\n\nAbans de comunicar es fixen <b>objectius</b> (donar a conèixer, informar, persuadir, recordar) i un <b>pressupost</b>: un percentatge de les vendes, el mateix que la competència, el que ens podem permetre o, millor, el necessari per complir l\'objectiu.',
  ejemplo='A Mercadeja, la publicitat a la ràdio local i les xarxes socials tenen sentit des del principi; l\'anunci a la televisió només quan ets gran empresa amb botigues a tota la comarca.',
  errores=['Triar el mitjà perquè és famós, no perquè arriba als teus clients.','Comunicar sense objectiu: no sabràs si ha funcionat.'],
  test=[('Quin és un mitjà publicitari i no un suport?',['La ràdio','Un programa concret de Catalunya Ràdio','El web d\'un diari concret','Una revista concreta'],0,'El mitjà és la categoria; el suport, el vehicle concret.'),
   ('Un objectiu de comunicació d\'una botiga que acaba d\'obrir sol ser…',['Recordar','Donar a conèixer (notorietat)','Fidelitzar els clients de sempre','Apujar els preus'],1,'Encara no la coneix ningú.'),
   ('Fixar el pressupost de publicitat com el 2 % de les vendes és el mètode…',['De l\'objectiu i la tasca','Del percentatge sobre vendes','De la paritat competitiva','Del que es pugui'],1,'És fàcil, però si les vendes baixen, es comunica menys just quan més falta fa.'),
   ('Quin instrument del mix de comunicació és un tast gratuït a la botiga?',['Publicitat','Promoció de vendes','Relacions públiques','Venda personal'],1,'És un incentiu a curt termini perquè el provin.')])),

dict(slug='promocion-ventas-relaciones-publicas', id='M_promocion', orden=24, codigos=['7.3', '7.4'], fase=1,
 es=dict(titulo='Promoción de ventas y relaciones públicas', objetivo='Diseñar promociones de ventas y acciones de relaciones públicas para una tienda.',
  tira=[[('eco','alegria','¡2×1 en todo, todos los días!')],[('nexo','esceptico','Si siempre hay oferta, ya no es una oferta. Y tu margen desaparece.')],[('nexo','guino','Promociones cortas y con objetivo. Y que el barrio hable bien de ti.')]],
  cos='La <b>promoción de ventas</b> son incentivos a corto plazo para que el cliente compre ahora: descuentos, 2×1, regalos, muestras y degustaciones, cupones, sorteos, packs. Funciona para lanzar productos, vaciar stock o atraer clientes en días flojos, pero si se repite siempre, los clientes se acostumbran y solo compran en oferta.\n\nLas <b>relaciones públicas</b> cuidan la imagen y la confianza: patrocinar el equipo del barrio, colaborar con una fiesta mayor, notas de prensa, eventos en la tienda, gestionar bien una queja pública. No venden directamente, pero mejoran la <b>reputación</b>, que hace que los clientes confíen y vuelvan.',
  ejemplo='En Mercadeja, la degustación atrae a los clientes que no te conocen, y patrocinar la fiesta mayor del barrio mejora tu reputación.',
  errores=['Hacer promociones continuamente y acostumbrar al cliente a no pagar nunca el precio normal.','Pensar que las relaciones públicas son «gratis»: cuestan tiempo y dinero, pero no son publicidad pagada en medios.'],
  test=[('¿Qué es una promoción de ventas?',['Un anuncio en la radio','Un 2×1 durante una semana','Patrocinar al equipo de fútbol','La atención del dependiente'],1,'Es un incentivo a corto plazo.'),
   ('Patrocinar la fiesta mayor del barrio es…',['Promoción de ventas','Relaciones públicas','Marketing directo','Publicidad en medios'],1,'Mejora la imagen y la relación con el entorno.'),
   ('¿Qué riesgo tienen las promociones continuas?',['Que nadie se entere','Que el cliente solo compre en oferta y caiga el margen','Que suban los precios','Que se agote la publicidad'],1,'Se pierde el valor del precio normal.'),
   ('Caso real · En 2018, KFC se quedó sin pollo en el Reino Unido y respondió con un anuncio en prensa que reordenaba sus siglas como «FCK» pidiendo disculpas. ¿Qué gestionaba?',['Una promoción de ventas','Su reputación (relaciones públicas en una crisis)','Un cambio de precio','Un nuevo canal de distribución'],1,'Una disculpa honesta y con humor ayudó a proteger la imagen de la marca.')]),
 ca=dict(titulo='Promoció de vendes i relacions públiques', objetivo='Dissenyar promocions de vendes i accions de relacions públiques per a una botiga.',
  tira=[[('eco','alegria','2×1 en tot, cada dia!')],[('nexo','esceptico','Si sempre hi ha oferta, ja no és una oferta. I el teu marge desapareix.')],[('nexo','guino','Promocions curtes i amb objectiu. I que el barri parli bé de tu.')]],
  cos='La <b>promoció de vendes</b> són incentius a curt termini perquè el client compri ara: descomptes, 2×1, regals, mostres i tastos, cupons, sortejos, lots. Funciona per llançar productes, buidar estoc o atraure clients en dies fluixos, però si es repeteix sempre, els clients s\'hi acostumen i només compren en oferta.\n\nLes <b>relacions públiques</b> tenen cura de la imatge i la confiança: patrocinar l\'equip del barri, col·laborar amb una festa major, notes de premsa, actes a la botiga, gestionar bé una queixa pública. No venen directament, però milloren la <b>reputació</b>, que fa que els clients confiïn i tornin.',
  ejemplo='A Mercadeja, el tast atrau els clients que no et coneixen, i patrocinar la festa major del barri millora la teva reputació.',
  errores=['Fer promocions contínuament i acostumar el client a no pagar mai el preu normal.','Pensar que les relacions públiques són «gratis»: costen temps i diners, però no són publicitat pagada en mitjans.'],
  test=[('Què és una promoció de vendes?',['Un anunci a la ràdio','Un 2×1 durant una setmana','Patrocinar l\'equip de futbol','L\'atenció del dependent'],1,'És un incentiu a curt termini.'),
   ('Patrocinar la festa major del barri és…',['Promoció de vendes','Relacions públiques','Màrqueting directe','Publicitat en mitjans'],1,'Millora la imatge i la relació amb l\'entorn.'),
   ('Quin risc tenen les promocions contínues?',['Que no se n\'assabenti ningú','Que el client només compri en oferta i baixi el marge','Que pugin els preus','Que s\'acabi la publicitat'],1,'Es perd el valor del preu normal.'),
   ('Cas real · El 2018, KFC es va quedar sense pollastre al Regne Unit i va respondre amb un anunci a la premsa que reordenava les seves sigles com a «FCK» demanant disculpes. Què gestionava?',['Una promoció de vendes','La seva reputació (relacions públiques en una crisi)','Un canvi de preu','Un canal de distribució nou'],1,'Una disculpa honesta i amb humor va ajudar a protegir la imatge de la marca.')])),

dict(slug='venta-personal-marketing-directo-fidelizacion', id='M_fidelizacion', orden=25, codigos=['7.5', '7.6'], fase=3,
 es=dict(titulo='Venta personal, marketing directo y fidelización', objetivo='Aplicar la venta personal y las técnicas de fidelización en una tienda.',
  tira=[[('eco','alegria','¡Hoy he conseguido 20 clientes nuevos!')],[('nexo','pensativo','¿Y cuántos de los de siempre no han vuelto?')],[('nexo','guino','Conservar un cliente cuesta menos que conseguir uno nuevo. Cuídalos.')]],
  cos='La <b>venta personal</b> es la comunicación cara a cara del vendedor con el cliente: detecta lo que necesita, aconseja y resuelve objeciones. Es cara, pero la más persuasiva.\n\nEl <b>marketing directo</b> envía mensajes personalizados a cada cliente (correo, SMS, WhatsApp, buzoneo con nombre) y permite medir quién responde. Necesita una base de datos de clientes que cumpla la normativa de protección de datos (consentimiento).\n\nEl <b>marketing relacional</b> busca relaciones duraderas: <b>tarjetas de fidelización</b> y puntos, ofertas para clientes habituales, atención posventa, clubes. Además de hacer volver al cliente, la tarjeta da información sobre qué compra cada uno.',
  ejemplo='En Mercadeja, desde el supermercado puedes crear una tarjeta de fidelización: regalas un 2 % en puntos, pero los clientes vuelven más a menudo.',
  errores=['Enviar publicidad personalizada sin el consentimiento del cliente.','Obsesionarse con captar clientes nuevos y olvidar a los actuales.'],
  test=[('¿Qué instrumento es más persuasivo, aunque más caro por cliente?',['La publicidad en televisión','La venta personal','El buzoneo','Los carteles'],1,'Se adapta a cada cliente en el momento.'),
   ('Un SMS con el nombre del cliente y una oferta de su producto favorito es…',['Marketing directo','Publicidad masiva','Relaciones públicas','Merchandising'],0,'Es un mensaje personalizado y medible.'),
   ('Además de hacer volver al cliente, la tarjeta de fidelización…',['Elimina la competencia','Da información sobre las compras de cada cliente','Baja los costes fijos','Sustituye la publicidad'],1,'Es una fuente de datos para el SIM.'),
   ('¿Qué necesitas para enviar ofertas por correo a tus clientes?',['Nada, si son clientes','Su consentimiento, según la normativa de protección de datos','Pagar un canon','Una tarjeta de crédito suya'],1,'El RGPD exige base legal (habitualmente el consentimiento).')]),
 ca=dict(titulo='Venda personal, màrqueting directe i fidelització', objetivo='Aplicar la venda personal i les tècniques de fidelització en una botiga.',
  tira=[[('eco','alegria','Avui he aconseguit 20 clients nous!')],[('nexo','pensativo','I quants dels de sempre no han tornat?')],[('nexo','guino','Conservar un client costa menys que aconseguir-ne un de nou. Cuida\'ls.')]],
  cos='La <b>venda personal</b> és la comunicació cara a cara del venedor amb el client: detecta què necessita, aconsella i resol objeccions. És cara, però la més persuasiva.\n\nEl <b>màrqueting directe</b> envia missatges personalitzats a cada client (correu, SMS, WhatsApp, bustiada amb nom) i permet mesurar qui respon. Necessita una base de dades de clients que compleixi la normativa de protecció de dades (consentiment).\n\nEl <b>màrqueting relacional</b> busca relacions duradores: <b>targetes de fidelització</b> i punts, ofertes per als clients habituals, atenció postvenda, clubs. A més de fer tornar el client, la targeta dona informació sobre què compra cadascú.',
  ejemplo='A Mercadeja, des del supermercat pots crear una targeta de fidelització: regales un 2 % en punts, però els clients tornen més sovint.',
  errores=['Enviar publicitat personalitzada sense el consentiment del client.','Obsessionar-se a captar clients nous i oblidar els actuals.'],
  test=[('Quin instrument és més persuasiu, tot i que més car per client?',['La publicitat a la televisió','La venda personal','La bustiada','Els cartells'],1,'S\'adapta a cada client en el moment.'),
   ('Un SMS amb el nom del client i una oferta del seu producte preferit és…',['Màrqueting directe','Publicitat massiva','Relacions públiques','Marxandatge'],0,'És un missatge personalitzat i mesurable.'),
   ('A més de fer tornar el client, la targeta de fidelització…',['Elimina la competència','Dona informació sobre les compres de cada client','Abaixa els costos fixos','Substitueix la publicitat'],1,'És una font de dades per al SIM.'),
   ('Què necessites per enviar ofertes per correu als teus clients?',['Res, si són clients','El seu consentiment, segons la normativa de protecció de dades','Pagar un cànon','Una targeta de crèdit seva'],1,'El RGPD exigeix base legal (habitualment el consentiment).')])),

dict(slug='comunicacion-digital-redes-sociales', id='M_digital', orden=26, codigos=['7.7'], fase=1,
 es=dict(titulo='Comunicación digital y redes sociales', objetivo='Usar las redes sociales y la comunicación digital de una tienda con criterio.',
  tira=[[('eco','alegria','¡Publico 10 veces al día en todas las redes!')],[('nexo','esceptico','¿En cuál están tus clientes? ¿Y qué les cuentas, aparte de «compra»?')],[('nexo','guino','Menos ruido y más utilidad: recetas, novedades, cómo trabajáis.')]],
  cos='La comunicación digital de una tienda incluye la <b>ficha de Google</b> (horario, fotos, reseñas), la <b>web</b>, las <b>redes sociales</b>, el <b>correo</b> y la <b>mensajería</b> (WhatsApp Business). Es barata, permite segmentar y medir, y es bidireccional: los clientes responden, comentan y valoran.\n\nPrincipios: elegir las redes donde está tu público, publicar contenido útil y propio (no solo ofertas), mantener una frecuencia regular, responder a los comentarios y reseñas (también a las malas) y medir los resultados (alcance, interacción, visitas, ventas).\n\nLos <b>creadores de contenido</b> e influencers pueden dar a conocer un producto, pero la colaboración pagada debe indicarse como publicidad.',
  ejemplo='Una tienda de barrio que publica cada semana una receta con productos de temporada y responde a todas las reseñas de Google gana visibilidad y confianza con poco presupuesto.',
  errores=['Estar en todas las redes sin tiempo para cuidarlas.','No responder a las reseñas negativas o hacerlo de malas maneras.'],
  test=[('¿Qué es lo primero que debería cuidar una tienda de barrio en internet?',['Un canal de TikTok con 1.000 vídeos','Su ficha de Google (horario, fotos, reseñas)','Un anuncio en televisión','Una app propia'],1,'Es lo que ve el cliente cuando busca la tienda.'),
   ('Un cliente deja una reseña negativa con razón. ¿Qué haces?',['La ignoras','Respondes con educación, pides disculpas y explicas cómo lo solucionas','La denuncias','Le contestas con otra reseña'],1,'Los demás clientes valoran cómo respondes.'),
   ('Una ventaja de la comunicación digital frente a la tradicional es que…',['Es siempre gratuita','Permite segmentar y medir los resultados','No necesita planificación','No tiene normativa'],1,'Puedes saber cuánta gente lo ha visto y qué ha hecho.'),
   ('Un influencer cobra por hablar de tu producto. ¿Qué debe hacer?',['Nada especial','Indicar que es publicidad o una colaboración pagada','Esconderlo para que sea creíble','Pedir permiso a la competencia'],1,'La ley obliga a identificar la comunicación comercial.')]),
 ca=dict(titulo='Comunicació digital i xarxes socials', objetivo='Fer servir les xarxes socials i la comunicació digital d\'una botiga amb criteri.',
  tira=[[('eco','alegria','Publico 10 vegades al dia a totes les xarxes!')],[('nexo','esceptico','A quina hi ha els teus clients? I què els expliques, a part de «compra»?')],[('nexo','guino','Menys soroll i més utilitat: receptes, novetats, com treballeu.')]],
  cos='La comunicació digital d\'una botiga inclou la <b>fitxa de Google</b> (horari, fotos, ressenyes), el <b>web</b>, les <b>xarxes socials</b>, el <b>correu</b> i la <b>missatgeria</b> (WhatsApp Business). És barata, permet segmentar i mesurar, i és bidireccional: els clients responen, comenten i valoren.\n\nPrincipis: triar les xarxes on és el teu públic, publicar contingut útil i propi (no només ofertes), mantenir una freqüència regular, respondre els comentaris i les ressenyes (també les dolentes) i mesurar els resultats (abast, interacció, visites, vendes).\n\nEls <b>creadors de contingut</b> i influencers poden donar a conèixer un producte, però la col·laboració pagada s\'ha d\'indicar com a publicitat.',
  ejemplo='Una botiga de barri que publica cada setmana una recepta amb productes de temporada i respon totes les ressenyes de Google guanya visibilitat i confiança amb poc pressupost.',
  errores=['Ser a totes les xarxes sense temps per cuidar-les.','No respondre les ressenyes negatives o fer-ho de males maneres.'],
  test=[('Què és el primer que hauria de cuidar una botiga de barri a internet?',['Un canal de TikTok amb 1.000 vídeos','La seva fitxa de Google (horari, fotos, ressenyes)','Un anunci a la televisió','Una app pròpia'],1,'És el que veu el client quan busca la botiga.'),
   ('Un client deixa una ressenya negativa amb raó. Què fas?',['La ignores','Respons amb educació, demanes disculpes i expliques com ho soluciones','La denuncies','Li contestes amb una altra ressenya'],1,'Els altres clients valoren com respons.'),
   ('Un avantatge de la comunicació digital davant de la tradicional és que…',['Sempre és gratuïta','Permet segmentar i mesurar els resultats','No necessita planificació','No té normativa'],1,'Pots saber quanta gent ho ha vist i què ha fet.'),
   ('Un influencer cobra per parlar del teu producte. Què ha de fer?',['Res d\'especial','Indicar que és publicitat o una col·laboració pagada','Amagar-ho perquè sigui creïble','Demanar permís a la competència'],1,'La llei obliga a identificar la comunicació comercial.')])),

dict(slug='plan-marketing-analisis-dafo', id='M_dafo', orden=27, codigos=['8.1', '8.2'], fase=1,
 es=dict(titulo='El plan de marketing: análisis y DAFO', objetivo='Conocer las fases del plan de marketing y hacer el análisis DAFO de una tienda.',
  tira=[[('eco','alegria','¡Mi plan es vender mucho!')],[('nexo','paciencia','Eso es un deseo. Un plan empieza por saber dónde estás: tus fuerzas, tus debilidades y lo que pasa fuera.')],[('eco','pensativo','Fuera y dentro… ¿como un DAFO?'),('nexo','guino','Exacto.')]],
  cos='El <b>plan de marketing</b> es el documento que ordena las decisiones de marketing de un periodo: 1) <b>análisis de la situación</b>, 2) <b>DAFO</b>, 3) <b>objetivos</b>, 4) <b>estrategias</b>, 5) <b>plan de acción</b> con las cuatro P, 6) <b>presupuesto</b> y 7) <b>control</b>.\n\nEl <b>DAFO</b> resume el análisis: <b>debilidades</b> y <b>fortalezas</b> son internas (dependen de la empresa: personal, ubicación, surtido, precios); <b>amenazas</b> y <b>oportunidades</b> son externas (entorno y competencia: un nuevo súper, una moda, una ley).\n\nDel DAFO salen las estrategias: aprovechar las fortalezas para las oportunidades, corregir las debilidades y defenderse de las amenazas.',
  ejemplo='Fortaleza: producto local de calidad. Debilidad: poco espacio. Oportunidad: más interés por la proximidad. Amenaza: el súper de descuento de enfrente. Estrategia: especializarse en producto local y comunicarlo.',
  errores=['Poner como oportunidad algo interno («tenemos buen personal» es una fortaleza).','Hacer un DAFO bonito y no sacar ninguna decisión.'],
  test=[('¿Qué es una amenaza?',['Tener poco espacio en la tienda','Que abra un supermercado de descuento al lado','Tener un buen equipo','Vender producto local'],1,'Es externa y negativa.'),
   ('«Nuestros dependientes conocen a todos los clientes» es…',['Una fortaleza','Una oportunidad','Una amenaza','Un objetivo'],0,'Es interna y positiva.'),
   ('¿Qué parte del plan va después del DAFO?',['El control','Los objetivos','El presupuesto','El plan de acción'],1,'Primero se analiza, después se decide adónde ir.'),
   ('Aumenta el interés por los productos de proximidad. Para una tienda de producto local es…',['Una fortaleza','Una debilidad','Una oportunidad','Una amenaza'],2,'Es un cambio externo favorable.')]),
 ca=dict(titulo='El pla de màrqueting: anàlisi i DAFO', objetivo='Conèixer les fases del pla de màrqueting i fer l\'anàlisi DAFO d\'una botiga.',
  tira=[[('eco','alegria','El meu pla és vendre molt!')],[('nexo','paciencia','Això és un desig. Un pla comença per saber on ets: les teves forces, les teves febleses i el que passa a fora.')],[('eco','pensativo','A fora i a dins… com un DAFO?'),('nexo','guino','Exacte.')]],
  cos='El <b>pla de màrqueting</b> és el document que ordena les decisions de màrqueting d\'un període: 1) <b>anàlisi de la situació</b>, 2) <b>DAFO</b>, 3) <b>objectius</b>, 4) <b>estratègies</b>, 5) <b>pla d\'acció</b> amb les quatre P, 6) <b>pressupost</b> i 7) <b>control</b>.\n\nEl <b>DAFO</b> resumeix l\'anàlisi: <b>debilitats</b> i <b>fortaleses</b> són internes (depenen de l\'empresa: personal, ubicació, assortiment, preus); <b>amenaces</b> i <b>oportunitats</b> són externes (entorn i competència: un súper nou, una moda, una llei).\n\nDel DAFO surten les estratègies: aprofitar les fortaleses per a les oportunitats, corregir les debilitats i defensar-se de les amenaces.',
  ejemplo='Fortalesa: producte local de qualitat. Debilitat: poc espai. Oportunitat: més interès per la proximitat. Amenaça: el súper de descompte del davant. Estratègia: especialitzar-se en producte local i comunicar-ho.',
  errores=['Posar com a oportunitat una cosa interna («tenim bon personal» és una fortalesa).','Fer un DAFO bonic i no treure\'n cap decisió.'],
  test=[('Què és una amenaça?',['Tenir poc espai a la botiga','Que obri un supermercat de descompte al costat','Tenir un bon equip','Vendre producte local'],1,'És externa i negativa.'),
   ('«Els nostres dependents coneixen tots els clients» és…',['Una fortalesa','Una oportunitat','Una amenaça','Un objectiu'],0,'És interna i positiva.'),
   ('Quina part del pla va després del DAFO?',['El control','Els objectius','El pressupost','El pla d\'acció'],1,'Primer s\'analitza, després es decideix on anar.'),
   ('Augmenta l\'interès pels productes de proximitat. Per a una botiga de producte local és…',['Una fortalesa','Una debilitat','Una oportunitat','Una amenaça'],2,'És un canvi extern favorable.')])),

dict(slug='plan-marketing-objetivos-accion-control', id='M_plan', orden=28, codigos=['8.3', '8.4', '8.5', '8.6'], fase=1,
 es=dict(titulo='Objetivos, plan de acción, presupuesto y control', objetivo='Fijar objetivos medibles, convertirlos en acciones con presupuesto y controlar si se cumplen.',
  tira=[[('eco','alegria','Objetivo: vender 500 € el sábado. ¡Hecho!')],[('nexo','pensativo','¿Y si vendes 380 €? ¿Qué cambiarás el domingo?')],[('nexo','guino','Sin control no hay plan: compara, busca la causa y corrige.')]],
  cos='Los <b>objetivos</b> deben ser concretos y medibles (SMART): «aumentar un 10 % las ventas de los sábados en dos meses». Las <b>estrategias</b> dicen cómo llegar (por ejemplo, atraer a familias con producto fresco). El <b>plan de acción</b> concreta qué se hará con cada P, quién y cuándo.\n\nEl <b>presupuesto</b> recoge lo que costará cada acción y los ingresos esperados. El <b>control</b> compara periódicamente los resultados con los objetivos, calcula las <b>desviaciones</b> y busca su causa para corregir: precio demasiado alto, falta de stock, comunicación que no llega…\n\nIndicadores habituales: ventas, margen, número de clientes, ticket medio, cuota de mercado, satisfacción.',
  ejemplo='En Mercadeja puedes fijar un objetivo de ventas cada mañana y, por la noche, comparar: si te quedas corto, el informe del día te dice si fue por el precio, por el stock o por la cola.',
  errores=['Fijar objetivos sin cifra ni plazo: no se pueden controlar.','Ver la desviación y no buscar la causa.'],
  test=[('Objetivo: 500 €. Resultado: 400 €. ¿Desviación?',['−100 € (−20 %)','+100 €','−25 %','400 €'],0,'(400 − 500) ÷ 500 = −20 %.'),
   ('¿Qué parte del plan concreta qué se hará, quién y cuándo?',['El DAFO','El plan de acción','El análisis de la situación','La misión'],1,'Convierte las estrategias en tareas.'),
   ('¿Qué es el ticket medio?',['El precio del producto más caro','Las ventas divididas por el número de clientes que compran','El número de tiques al día','El margen por cliente'],1,'Cuánto gasta de media cada cliente.'),
   ('Las ventas han bajado y muchos clientes encontraban la estantería vacía. ¿Qué medida correctora tiene sentido?',['Bajar los precios de todo','Mejorar la previsión de compras y la reposición','Hacer más publicidad','Cambiar el logotipo'],1,'La causa es la distribución (stock), no el precio ni la comunicación.')]),
 ca=dict(titulo='Objectius, pla d\'acció, pressupost i control', objetivo='Fixar objectius mesurables, convertir-los en accions amb pressupost i controlar si es compleixen.',
  tira=[[('eco','alegria','Objectiu: vendre 500 € dissabte. Fet!')],[('nexo','pensativo','I si en vens 380 €? Què canviaràs diumenge?')],[('nexo','guino','Sense control no hi ha pla: compara, busca la causa i corregeix.')]],
  cos='Els <b>objectius</b> han de ser concrets i mesurables (SMART): «augmentar un 10 % les vendes dels dissabtes en dos mesos». Les <b>estratègies</b> diuen com arribar-hi (per exemple, atraure famílies amb producte fresc). El <b>pla d\'acció</b> concreta què es farà amb cada P, qui i quan.\n\nEl <b>pressupost</b> recull què costarà cada acció i els ingressos esperats. El <b>control</b> compara periòdicament els resultats amb els objectius, calcula les <b>desviacions</b> i en busca la causa per corregir: preu massa alt, manca d\'estoc, comunicació que no arriba…\n\nIndicadors habituals: vendes, marge, nombre de clients, tiquet mitjà, quota de mercat, satisfacció.',
  ejemplo='A Mercadeja pots fixar un objectiu de vendes cada matí i, al vespre, comparar: si et quedes curt, l\'informe del dia et diu si va ser pel preu, per l\'estoc o per la cua.',
  errores=['Fixar objectius sense xifra ni termini: no es poden controlar.','Veure la desviació i no buscar-ne la causa.'],
  test=[('Objectiu: 500 €. Resultat: 400 €. Desviació?',['−100 € (−20 %)','+100 €','−25 %','400 €'],0,'(400 − 500) ÷ 500 = −20 %.'),
   ('Quina part del pla concreta què es farà, qui i quan?',['El DAFO','El pla d\'acció','L\'anàlisi de la situació','La missió'],1,'Converteix les estratègies en tasques.'),
   ('Què és el tiquet mitjà?',['El preu del producte més car','Les vendes dividides pel nombre de clients que compren','El nombre de tiquets al dia','El marge per client'],1,'Quant gasta de mitjana cada client.'),
   ('Les vendes han baixat i molts clients trobaven la prestatgeria buida. Quina mesura correctora té sentit?',['Abaixar els preus de tot','Millorar la previsió de compres i la reposició','Fer més publicitat','Canviar el logotip'],1,'La causa és la distribució (estoc), no el preu ni la comunicació.')])),
]
